mapper.sql:
h.tenant_id = #{tenantId}
and h.user_id = #{userId}
and h.del_flag = '0'

    and h.status = #{query.status}


    and h.portfolio_id = #{query.portfolioId}


    and exists (
        select 1
        from biz_user_fund_group_relation grf
        where grf.tenant_id = h.tenant_id
          and grf.user_id = h.user_id
          and grf.holding_id = h.id
          and grf.group_id = #{query.groupId}
          and grf.del_flag = '0'
    )
